    def payload(value, prefix, v=vars, dec=decode):
        data = dec(value) if value else {}
        if isinstance(data, dict) and data:
            return data
        tree = {}
        if not prefix:
            return tree
        for key, raw in v.items():
            if not key.startswith(prefix):
                continue
            parts = key[len(prefix):].split('.')
            branch = tree
            for part in parts[:-1]:
                branch = branch.setdefault(part, {})
            val = raw
            if raw == 'true':
                val = True
            elif raw == 'false':
                val = False
            elif isinstance(raw, str) and raw.lstrip().startswith(('[', '{')):
                val = dec(raw)
            branch[parts[-1]] = val
        if isinstance(tree.get('cards'), dict):
            tree['cards'] = [tree['cards'][k] for k in sorted(tree['cards'], key=lambda x: int(x))]
        return tree
    kinds = ['neutral', 'answer', 'yes', 'no', 'unclear', 'refuse', 'repeat', 'silence', 'agent', 'pay', 'dispute', 'third_party', 'non_turkish', 'outside', 'angry', 'privacy', 'secret', 'all_cards', 'card', 'email', 'week', 'done', 'stop', 'undo', 'effective', 'ai']
    text_keys = ['u_card', 'u_digits', 'u_detail_request']
    enums = dict(u_kind=kinds, u_digit_mode=['neutral', 'append', 'replace'], u_detail=['neutral', 'all', 'due', 'minimum', 'total'], u_followup=['neutral', 'email', 'week'], u_currency=['neutral', 'TL', 'USD', 'EUR', 'GBP', 'unclear'], u_period=['neutral', 'latest', 'older'], u_week=['neutral', '1', '2', '3', '4', 'invalid'], u_destination=['neutral', 'registered', 'other', 'wrong', 'paper', 'sms'])
    keys = list(enums) + text_keys
    def clean_input(raw, fields=keys, texts=text_keys, options=enums, normalize_alias=alias):
        if not isinstance(raw, dict):
            raw = dict(u_kind='unclear')
        clean = {}
        invalid = False
        for name in fields:
            value = raw.get(name, '' if name in texts else 'neutral')
            if name in texts:
                if not isinstance(value, str):
                    invalid = True
                    value = ''
            elif value not in options[name]:
