            clean[name] = value
        if clean['u_card'] and not normalize_alias(clean['u_card']):
            clean['u_card'] = ''
            if clean['u_kind'] == 'card' and not clean['u_digits']:
                clean['u_kind'] = 'answer'
        if invalid:
            clean['u_kind'] = 'unclear'
        return clean
