            parts = key[len(prefix):].split('.')
            branch = tree
            for part in parts[:-1]:
                branch = branch.setdefault(part, {})
            val = raw
            if raw == 'true':
                val = True
            elif raw == 'false':
                val = False
            elif isinstance(raw, str) and raw.lstrip().startswith(('[', '{')):
                val = dec(raw)
            branch[parts[-1]] = val
