            text += ' hesap kesim tarihi her ayın ' + ordinals[int(info['statementWeek'])] + ' haftası olarak tanımlı.'
            if info.get('nextStatementDate'):
                text += ' Bir sonraki hesap kesim tarihiniz ' + date_speech(info['nextStatementDate']) + '.'
            if info.get('nextLastPayDate'):
                text += ' Son ödeme tarihiniz ' + date_speech(info['nextLastPayDate']) + '.'
            question('week_current', text + ' Hesap kesim tarihinizi değiştirmek ister misiniz?', 'Hesap kesim tarihinizi değiştirmek ister misiniz?')
        elif phase == 'week_choose':
            options = [n for n in [1, 2, 3, 4] if n != int(vars['week_info']['statementWeek'])]
            question('week_choose', 'Hesap kesim tarihinizi ayın ' + joined([ordinals[n] for n in options]) + ' haftalarından birine alabilirim. Hangisini tercih edersiniz?')
        elif phase == 'week_confirm':
            info, preview = vars['week_info'], vars['preview']
            text = ''
            if info.get('relationType') in ['M', 'C']:
                related_name = safe_name(info.get('relatedCardProductName', '')) or 'diğer'
                text = 'Bu değişiklik ' + ('kartınıza bağlı ' if info['relationType'] == 'M' else 'kartınızın bağlı olduğu ') + related_name + ' kartınızı da etkileyecek. '
            text += 'Yeni hesap kesim haftanız her ayın ' + ordinals[int(vars['preview_week'])] + ' haftası olacak. Yeni hesap kesim tarihiniz ' + date_speech(preview['statementDate']) + ', son ödeme tarihiniz ' + date_speech(preview['statementDueDate']) + ' olacak. Onaylıyor musunuz?'
            vars['week_challenge'] = dict(cardNumber=card['cardNumber'], newStatementWeek=int(vars['preview_week']), statementDay=int(info['statementDay']), statementDate=preview['statementDate'], statementDueDate=preview['statementDueDate'], relationType=info.get('relationType', ''), relatedCardNumber=info.get('relatedCardNumber', ''))
            question('week_confirm', text, text, 'week:confirm:' + card['cardNumber'] + ':' + str(vars['preview_week']))
        elif phase == 'finished':
            vars['route'] = 'finish'
    deferred = decode(vars.get('deferred_input', {}))
    if deferred and not global_handled and vars['phase'] != 'finished' and vars['route'] != 'evaluate':
        deferred = clean_input(deferred)
        if event == 'cards_list' and vars['route'] in ['choose_card', 'balance_lookup']:
            vars['deferred_input'] = {}
            vars['replay_input'] = deferred
            vars['phase'] = 'choose_card'
            vars['selection_initial'] = 'yes'
            vars['route'] = 'evaluate'
        elif event and event != 'cards_list' and (deferred['u_kind'] in ['card', 'all_cards'] or deferred['u_card']):
            vars['deferred_input'] = {}
            vars['replay_input'] = deferred
            vars['phase'] = 'choose_card'
            vars['selection_candidates'] = []
            vars['selection_width'] = 4
            vars['selection_step'] = 'name'
            vars['digits_buffer'] = ''
            vars['write_gate'] = 'no'
            vars['preview_ready'] = 'no'
            vars['week_challenge'] = {}
            vars['email_challenge'] = {}
            vars['reading_prefix'] = ''
            vars['wanted_detail'] = 'all'
            vars['detail_request'] = ''
            vars['wanted_currency'] = 'neutral'
            vars['wanted_period'] = 'latest'
            vars['destination_request'] = 'neutral'
            vars['pending_followup'] = 'neutral'
            vars['early_week'] = 0
            vars['route'] = 'evaluate'
    if not vars['route']:
        raise ValueError('uninitialized_route')
except Exception as exc:
    vars['diagnostic'] = str(type(exc)) + ': evaluate_policy_or_prerequisite'
    week_error = str(vars.get('operation_before_error', '')).startswith('statement_week_') or str(vars.get('phase_before_error', '')).startswith(('week', 'preview', 'change'))
    vars['bank_event'] = ''
    vars['bank_pending'] = ''
    vars['bank_payload'] = {}
    vars['arrival_input'] = {}
    vars['replay_input'] = {}
    vars['deferred_input'] = {}
    vars['after_contact'] = ''
    vars['write_gate'] = 'no'
    vars['route'] = 'finish'
    vars['phase'] = 'finished'
    vars['handoff_destination'] = 'agent'
    vars['speech'] = 'Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.' if week_error else 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
